/**
 * ThemedFormControlLabel Component Overrides
 *
 * Notes:
 * 1. Styling Guidelines:
 *    - Prefer styling with `root` and `label` properties for customizations.
 *    - Use class-based styling (e.g., `Mui-disabled`) when necessary for higher specificity
 *      or when object-based styling doesn't suffice (e.g., for complex state-based hover or focus effects).
 *
 * 2. Focus and Hover:
 *    - The `&:has(input:focus-visible)` selector targets the root element when the inner input (checkbox/radio) is focused.
 *    - The `&:hover` selector handles hover effects, including for the `outlined` variant and when the component is in a checked or error state.
 *
 * 3. Disabled and Error States:
 *    - Disabled state styling is managed via `ownerState.disabled`.
 *    - Error states are styled through `&:has(.MuiCheckbox-colorError)` and similar selectors to target inputs
 *      that have been explicitly passed `color="error"` by the consumer.
 *    - This approach allows more granular control over which form options are displayed with error colors,
 *      especially when some selections in an error state form are valid, while others are not.
 *    - `ownerState.error` is used for handling error states globally within forms, but the `color="error"` prop
 *      gives finer control at the individual input level.
 */
export const createThemedFormControlLabel = (overrides) => ({
    defaultProps: {
        labelPlacement: "start",
        variant: "standard",
    },
    styleOverrides: {
        label: ({ ownerState, theme }) => ({
            ...(ownerState.variant === "outlined" && {
                "&.Mui-disabled": {
                    color: theme.palette.components?.formControlLabel?.label.disabled,
                },
            }),
        }),
        root: ({ ownerState, theme, ...rest }) => ({
            ...(ownerState.variant === "outlined" && {
                backgroundColor: theme.palette.components?.formControlLabel?.background.main,
                border: `1px solid ${theme.palette.components?.formControlLabel?.border.main}`,
                color: theme.palette.components?.formControlLabel?.label.main,
                marginLeft: 0,
                ...(ownerState.labelPlacement === "end" && {
                    paddingRight: "16px",
                }),
                ...(ownerState.labelPlacement === "start" && {
                    paddingLeft: "16px",
                }),
                ...(ownerState.labelPlacement === "top" && {
                    padding: "16px 16px 0 16px",
                }),
                ...(ownerState.labelPlacement === "bottom" && {
                    padding: "0 16px 16px 16px",
                }),
                ...(ownerState.disabled && {
                    backgroundColor: theme.palette.components?.formControlLabel?.background.disabled,
                    border: `1px solid ${theme.palette.components?.formControlLabel?.border.disabled}`,
                }),
                ...(!ownerState.disabled && {
                    "& .MuiCheckbox-root:hover, & .MuiRadio-root:hover": {
                        backgroundColor: "transparent",
                    },
                    // When the input has `color="error"`
                    "&:has(.MuiCheckbox-colorError), &:has(.MuiRadio-colorError)": {
                        // When the input is checked
                        "&:has(input:checked)": {
                            backgroundColor: theme.palette.components?.formControlLabel?.background.error,
                            borderColor: theme.palette.components?.formControlLabel?.border.error,
                        },
                        backgroundColor: theme.palette.components?.formControlLabel?.background.error,
                        borderColor: theme.palette.components?.formControlLabel?.border.error,
                    },
                    // When the input is checked
                    "&:has(input:checked)": {
                        "&:hover": {
                            backgroundColor: theme.palette.components?.formControlLabel?.background.hover,
                        },
                        backgroundColor: theme.palette.components?.formControlLabel?.background.selected,
                    },
                    "&:hover": {
                        backgroundColor: theme.palette.components?.formControlLabel?.background.hover,
                    },
                    color: theme.palette.components?.formControlLabel?.label.main,
                }),
                // Target the root when the input inside is focused
                "&:has(input:focus-visible)": {
                    backgroundColor: theme.palette.components?.formControlLabel?.background.focused,
                    outline: `2px solid ${theme.palette.components?.formControlLabel?.focusRing}`,
                    outlineOffset: "2px",
                },
            }),
            ...(ownerState.labelPlacement === "start" && {
                "&:has(.MuiSwitch-root)": {
                    "& .MuiFormControlLabel-label": {
                        textAlign: "left",
                    },
                    "& > .MuiFormControlLabel-label, & > div": {
                        flex: 1,
                        textAlign: "left",
                    },
                    marginLeft: 0,
                },
            }),
            ...(typeof overrides?.styleOverrides?.root === "function" &&
                overrides?.styleOverrides?.root?.({
                    ownerState,
                    theme,
                    ...rest,
                })),
        }),
    },
});
